export const corporateFunctionBaselineHtml = "<!-- ===================== SERVICES — CORPORATE FUNCTION (INFOGRAPHIC – FIXED SPINE GAPS + MOBILE OPTIMIZED) ===================== -->\r\n<link href=\"https://fonts.googleapis.com/css2?family=Poppins:wght@400;500;600;700;800;900&display=swap\" rel=\"stylesheet\"/>\r\n\r\n<style>\r\n  :root{\r\n    /* brand colours */\r\n    --navy:#020C4F;\r\n    --indigo:#313B86;\r\n    --violet:#625AD8;\r\n    --accent:#1F9CE4;\r\n\r\n    --ink:#0B0F1A;\r\n    --muted:#3C4160;\r\n    --line:rgba(49,59,134,.16);\r\n    --line2:rgba(49,59,134,.18);\r\n    --card:#ffffff;\r\n\r\n    /* widened max width */\r\n    --max:1320px;\r\n\r\n    /* header height for aligning spine */\r\n    --colHeadH: 36px;\r\n\r\n    /* how far connectors travel horizontally */\r\n    --connector: 70px;\r\n  }\r\n\r\n  .cfInf, .cfInf *{ box-sizing:border-box; }\r\n\r\n  /* stop any horizontal scroll caused by long words / grid / pills */\r\n  .cfInf{ overflow-x:hidden; }\r\n\r\n  .cfInf{\r\n    font-family:'Poppins',system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\r\n    color:var(--ink);\r\n    background:#fff;\r\n    padding:86px 20px 78px;\r\n  }\r\n\r\n  .cfInf__inner{ max-width:var(--max); margin:0 auto; }\r\n\r\n  /* ---------- Header ---------- */\r\n  .cfInf__kicker{\r\n    margin:0 0 10px;\r\n    font-size:12px;\r\n    letter-spacing:.22em;\r\n    text-transform:uppercase;\r\n    color:var(--indigo);\r\n    font-weight:900;\r\n  }\r\n  .cfInf__title{\r\n    margin:0 0 10px;\r\n    /* smaller title than original */\r\n    font-size:clamp(26px,3.1vw,36px);\r\n    line-height:1.15;\r\n    font-weight:950;\r\n    color:var(--navy);\r\n    max-width:980px;\r\n  }\r\n  .cfInf__sub{\r\n    margin:0 0 22px;\r\n    font-size:15.5px;\r\n    line-height:1.8;\r\n    color:var(--muted);\r\n    max-width:980px;\r\n  }\r\n\r\n  /* ---------- Shell ---------- */\r\n  .cfInf__frame{\r\n    border:1px solid rgba(49,59,134,.16);\r\n    border-radius:26px;\r\n    background:rgba(255,255,255,.98);\r\n    box-shadow:0 18px 46px rgba(0,0,0,.06);\r\n    overflow:hidden; /* keeps desktop clean */\r\n  }\r\n\r\n  /* top helper bar */\r\n  .cfInf__bar{\r\n    padding:14px 16px;\r\n    border-bottom:1px solid rgba(49,59,134,.12);\r\n    display:flex;\r\n    align-items:center;\r\n    justify-content:space-between;\r\n    gap:12px;\r\n    background:\r\n      radial-gradient(circle at 0% 0%, rgba(98,90,216,.10), transparent 55%),\r\n      radial-gradient(circle at 100% 0%, rgba(31,156,228,.10), transparent 55%),\r\n      #fff;\r\n  }\r\n  .cfInf__badge{\r\n    display:inline-flex;\r\n    align-items:center;\r\n    gap:10px;\r\n    padding:8px 10px;\r\n    border-radius:999px;\r\n    border:1px solid rgba(49,59,134,.16);\r\n    background:rgba(49,59,134,.03);\r\n    color:var(--navy);\r\n    font-size:12px;\r\n    font-weight:900;\r\n    white-space:nowrap;\r\n  }\r\n  .cfInf__badgeDot{\r\n    width:9px;height:9px;border-radius:999px;\r\n    background:linear-gradient(135deg,var(--violet),var(--accent));\r\n    box-shadow:0 0 0 6px rgba(31,156,228,.10);\r\n  }\r\n  .cfInf__barRight{\r\n    display:inline-flex;\r\n    align-items:center;\r\n    gap:10px;\r\n    padding:8px 10px;\r\n    border-radius:999px;\r\n    border:1px solid rgba(49,59,134,.14);\r\n    background:#fff;\r\n    color:var(--indigo);\r\n    font-size:11.5px;\r\n    font-weight:900;\r\n    letter-spacing:.10em;\r\n    text-transform:uppercase;\r\n    white-space:nowrap;\r\n  }\r\n\r\n  /* ---------- 2-column infographic body with spine ---------- */\r\n  .cfInf__body{\r\n    position:relative;\r\n    display:grid;\r\n    grid-template-columns:minmax(0,1fr) 160px minmax(0,1fr);\r\n    gap:0;\r\n    align-items:stretch;\r\n    padding:22px 26px 22px;\r\n  }\r\n\r\n  /* header row auto, 3 cards equal height */\r\n  .cfInf__col{\r\n    min-width:0;\r\n    display:grid;\r\n    grid-template-rows:auto repeat(3,1fr);\r\n    row-gap:22px; /* vertical space between header and cards, and between cards */\r\n  }\r\n\r\n  .cfInf__col--left{ padding-right:14px; }\r\n  .cfInf__col--right{ padding-left:14px; }\r\n\r\n  .cfInf__colHead{\r\n    min-height:auto;\r\n    display:flex;\r\n    align-items:flex-end;\r\n    justify-content:space-between;\r\n    gap:10px;\r\n    padding:2px 4px 0;\r\n  }\r\n  .cfInf__colTitle{\r\n    margin:0;\r\n    font-size:13px;\r\n    letter-spacing:.18em;\r\n    text-transform:uppercase;\r\n    color:var(--navy);\r\n    font-weight:950;\r\n  }\r\n  .cfInf__colNote{\r\n    margin:0;\r\n    font-size:12.5px;\r\n    color:#5B6282;\r\n    font-weight:700;\r\n    white-space:nowrap;\r\n  }\r\n\r\n  .cfInf__group{\r\n    position:relative;\r\n    border:1px solid rgba(49,59,134,.14);\r\n    border-radius:18px;\r\n    background:#fff;\r\n    padding:18px 16px 20px; /* more internal space */\r\n    box-shadow:0 10px 26px rgba(0,0,0,.04);\r\n    height:100%; /* stretch inside column grid */\r\n  }\r\n\r\n  .cfInf__groupKicker{\r\n    margin:0 0 6px;\r\n    font-size:11.5px;\r\n    letter-spacing:.16em;\r\n    text-transform:uppercase;\r\n    color:var(--indigo);\r\n    font-weight:900;\r\n  }\r\n\r\n  .cfInf__groupTitle{\r\n    margin:0 0 10px;\r\n    font-size:15.5px;\r\n    line-height:1.25;\r\n    font-weight:950;\r\n    color:var(--navy);\r\n  }\r\n\r\n  .cfInf__list{\r\n    margin:0;\r\n    padding:0;\r\n    list-style:none;\r\n    display:grid;\r\n    gap:10px;\r\n  }\r\n  .cfInf__li{\r\n    display:flex;\r\n    gap:10px;\r\n    align-items:flex-start;\r\n    font-size:14.2px;\r\n    line-height:1.65;\r\n    color:#2E334D;\r\n  }\r\n\r\n  /* clean, consistent icon for all bullets */\r\n  .cfInf__dot{\r\n    width:10px;\r\n    height:10px;\r\n    border-radius:999px;\r\n    margin-top:7px;\r\n    flex:0 0 auto;\r\n    background:linear-gradient(135deg,var(--violet),var(--accent));\r\n    outline:3px solid rgba(31,156,228,.12);\r\n  }\r\n\r\n  /* remove special first/last margins so spacing is equal via grid-gap */\r\n  .cfInf__col--left .cfInf__group:first-of-type,\r\n  .cfInf__col--right .cfInf__group:first-of-type,\r\n  .cfInf__col--left .cfInf__group:last-of-type,\r\n  .cfInf__col--right .cfInf__group:last-of-type{\r\n    margin-top:0;\r\n    margin-bottom:0;\r\n  }\r\n\r\n  /* ---------- Spine (desktop, absolute labels) ---------- */\r\n  .cfInf__spine{ position:relative; }\r\n\r\n  .cfInf__spineLine{\r\n    position:absolute;\r\n    left:50%;\r\n    transform:translateX(-50%);\r\n    top:var(--colHeadH);\r\n    bottom:0;\r\n    width:4px;\r\n    border-radius:999px;\r\n    background:linear-gradient(180deg,var(--accent),var(--violet));\r\n    opacity:.9;\r\n    z-index:0;\r\n  }\r\n\r\n  .cfInf__spineLabel{\r\n    position:absolute;\r\n    left:50%;\r\n    transform:translateX(-50%);\r\n    z-index:2;\r\n    width:max-content;\r\n    /* narrower so it stays inside the centre column */\r\n    max-width:140px;\r\n    text-align:center;\r\n    font-size:11px;\r\n    letter-spacing:.14em;\r\n    text-transform:uppercase;\r\n    font-weight:950;\r\n    color:var(--navy);\r\n    padding:7px 10px;\r\n    border-radius:999px;\r\n    border:1px solid rgba(49,59,134,.16);\r\n    background:rgba(255,255,255,.96);\r\n    box-shadow:0 10px 22px rgba(0,0,0,.06);\r\n    line-height:1.15;\r\n    pointer-events:none;\r\n  }\r\n  .cfInf__spineLabel--top{ top:calc(var(--colHeadH) + 12px); }\r\n  .cfInf__spineLabel--bottom{ bottom:24px; }\r\n\r\n  .cfInf__spineNode{\r\n    position:absolute;\r\n    left:50%;\r\n    top:50%;\r\n    transform:translate(-50%,-50%);\r\n    z-index:2;\r\n    width:46px;height:46px;\r\n    border-radius:16px;\r\n    background:#fff;\r\n    border:1px solid rgba(49,59,134,.18);\r\n    box-shadow:0 14px 34px rgba(0,0,0,.10);\r\n    display:grid;\r\n    place-items:center;\r\n    color:var(--navy);\r\n    font-weight:950;\r\n    pointer-events:none;\r\n  }\r\n  .cfInf__spineNode::after{\r\n    content:\"\";\r\n    position:absolute;\r\n    inset:-10px;\r\n    border-radius:20px;\r\n    background:linear-gradient(135deg, rgba(98,90,216,.16), rgba(31,156,228,.10));\r\n    z-index:-1;\r\n  }\r\n\r\n  /* ---------- CONNECTOR LINES (DESKTOP ONLY) ---------- */\r\n  .cfInf__col--left .cfInf__group::after{\r\n    content:\"\";\r\n    position:absolute;\r\n    right:calc(var(--connector) * -1);\r\n    top:26px;\r\n    width:var(--connector);\r\n    height:1px;\r\n    background:var(--line2);\r\n  }\r\n  .cfInf__col--left .cfInf__group::before{\r\n    content:\"\";\r\n    position:absolute;\r\n    right:calc(var(--connector) * -1 - 6px);\r\n    top:23px;\r\n    width:7px;height:7px;\r\n    border-radius:999px;\r\n    background:rgba(31,156,228,.22);\r\n    outline:3px solid rgba(31,156,228,.10);\r\n  }\r\n\r\n  .cfInf__col--right .cfInf__group::before{\r\n    content:\"\";\r\n    position:absolute;\r\n    left:calc(var(--connector) * -1);\r\n    top:26px;\r\n    width:var(--connector);\r\n    height:1px;\r\n    background:var(--line2);\r\n  }\r\n  .cfInf__col--right .cfInf__group::after{\r\n    content:\"\";\r\n    position:absolute;\r\n    left:calc(var(--connector) * -1 - 6px);\r\n    top:23px;\r\n    width:7px;height:7px;\r\n    border-radius:999px;\r\n    background:rgba(31,156,228,.22);\r\n    outline:3px solid rgba(31,156,228,.10);\r\n  }\r\n\r\n  /* ---------- Impact bar ---------- */\r\n  .cfInf__impact{\r\n    padding:16px 18px 18px;\r\n    border-top:1px solid rgba(49,59,134,.12);\r\n    background:rgba(49,59,134,.02);\r\n  }\r\n  .cfInf__impactRow{\r\n    display:flex;\r\n    align-items:flex-start;\r\n    justify-content:space-between;\r\n    gap:12px;\r\n    flex-wrap:wrap;\r\n  }\r\n  .cfInf__impactTitle{\r\n    margin:0;\r\n    font-size:12px;\r\n    letter-spacing:.18em;\r\n    text-transform:uppercase;\r\n    font-weight:950;\r\n    color:var(--navy);\r\n  }\r\n  .cfInf__chips{\r\n    display:flex;\r\n    flex-wrap:wrap;\r\n    gap:10px;\r\n    align-items:center;\r\n  }\r\n  .cfInf__chip{\r\n    display:inline-flex;\r\n    align-items:center;\r\n    gap:8px;\r\n    height:34px;\r\n    padding:0 12px;\r\n    border-radius:999px;\r\n    border:1px solid rgba(49,59,134,.16);\r\n    background:#fff;\r\n    color:var(--navy);\r\n    font-size:12px;\r\n    font-weight:900;\r\n    white-space:nowrap;\r\n  }\r\n  .cfInf__chip i{\r\n    width:7px;height:7px;border-radius:999px;\r\n    background:linear-gradient(135deg,var(--violet),var(--accent));\r\n    display:inline-block;\r\n  }\r\n\r\n  /* =======================================================================\r\n     MOBILE / TABLET OPTIMIZATION\r\n     ======================================================================= */\r\n  @media (max-width:1024px){\r\n    .cfInf{ padding:68px 14px 62px; }\r\n\r\n    .cfInf__frame{ border-radius:18px; }\r\n\r\n    .cfInf__body{\r\n      grid-template-columns:1fr;\r\n      gap:14px;\r\n      padding:14px 12px 14px;\r\n    }\r\n\r\n    .cfInf__col--left,\r\n    .cfInf__col--right{ padding:0; }\r\n\r\n    .cfInf__colHead{\r\n      min-height:auto;\r\n      flex-direction:column;\r\n      align-items:flex-start;\r\n      gap:4px;\r\n      padding:0 2px;\r\n    }\r\n    .cfInf__colNote{ white-space:normal; }\r\n\r\n    .cfInf__group::before,\r\n    .cfInf__group::after{ display:none !important; }\r\n\r\n    .cfInf__spine{\r\n      display:grid;\r\n      grid-template-columns:1fr auto 1fr;\r\n      grid-template-rows:auto auto;\r\n      align-items:center;\r\n      gap:10px 10px;\r\n      padding:10px 6px 6px;\r\n      position:relative;\r\n    }\r\n\r\n    .cfInf__spineLine{\r\n      position:absolute;\r\n      left:0;\r\n      right:0;\r\n      top:50%;\r\n      bottom:auto;\r\n      transform:none;\r\n      width:auto;\r\n      height:4px;\r\n      border-radius:999px;\r\n    }\r\n\r\n    .cfInf__spineLabel{\r\n      position:relative;\r\n      left:auto;\r\n      transform:none;\r\n      max-width:100%;\r\n      width:100%;\r\n      font-size:10px;\r\n      padding:6px 8px;\r\n      box-shadow:0 8px 18px rgba(0,0,0,.06);\r\n      pointer-events:none;\r\n    }\r\n\r\n    .cfInf__spineLabel--top{\r\n      grid-column:1;\r\n      grid-row:1;\r\n      justify-self:start;\r\n      top:auto;\r\n    }\r\n    .cfInf__spineLabel--bottom{\r\n      grid-column:3;\r\n      grid-row:1;\r\n      justify-self:end;\r\n      bottom:auto;\r\n    }\r\n\r\n    .cfInf__spineNode{\r\n      position:relative;\r\n      left:auto;\r\n      top:auto;\r\n      transform:none;\r\n      grid-column:2;\r\n      grid-row:2;\r\n      justify-self:center;\r\n      width:44px;height:44px;\r\n      border-radius:16px;\r\n      margin:0;\r\n      pointer-events:none;\r\n    }\r\n  }\r\n\r\n  @media (max-width:680px){\r\n    .cfInf__bar{ flex-direction:column; align-items:flex-start; gap:10px; }\r\n    .cfInf__barRight{ width:100%; justify-content:center; white-space:normal; text-align:center; }\r\n\r\n    .cfInf__title{ font-size:clamp(24px,7vw,32px); }\r\n    .cfInf__sub{ font-size:14.6px; line-height:1.75; }\r\n\r\n    .cfInf__group{ padding:14px; border-radius:16px; }\r\n    .cfInf__groupTitle{ font-size:15px; }\r\n    .cfInf__li{ font-size:13.8px; }\r\n\r\n    .cfInf__impactRow{ flex-direction:column; align-items:flex-start; }\r\n    .cfInf__chips{ gap:8px; }\r\n    .cfInf__chip{ height:32px; font-size:11.5px; }\r\n  }\r\n</style>\r\n\r\n<section class=\"cfInf\" id=\"corporate-function-spine\">\r\n  <div class=\"cfInf__inner\">\r\n    <p class=\"cfInf__kicker\">Corporate Function</p>\r\n    <h2 class=\"cfInf__title\">From fragmented support functions to an integrated corporate backbone</h2>\r\n    <p class=\"cfInf__sub\">\r\n      Corporate Function Transformation unifies HR, Finance, IT, Risk, and other enterprise functions\r\n      into a data-driven, future-ready backbone—reducing overheads while strengthening control,\r\n      transparency, and productivity.\r\n    </p>\r\n\r\n    <div class=\"cfInf__frame\" role=\"region\" aria-label=\"Corporate function transformation spine infographic\">\r\n      <div class=\"cfInf__bar\">\r\n        <div class=\"cfInf__badge\">\r\n          <span class=\"cfInf__badgeDot\" aria-hidden=\"true\"></span>\r\n          CF Transformation Framework\r\n        </div>\r\n        <div class=\"cfInf__barRight\">Governance • Shared Services • Automation</div>\r\n      </div>\r\n\r\n      <div class=\"cfInf__body\">\r\n        <!-- LEFT: What we typically see -->\r\n        <div class=\"cfInf__col cfInf__col--left\">\r\n          <div class=\"cfInf__colHead\">\r\n            <p class=\"cfInf__colTitle\">What we typically see</p>\r\n            <p class=\"cfInf__colNote\">Fragmented, cost-heavy corporate functions</p>\r\n          </div>\r\n\r\n          <article class=\"cfInf__group\">\r\n            <p class=\"cfInf__groupKicker\">Structure &amp; Ways of Working</p>\r\n            <h3 class=\"cfInf__groupTitle\">Siloed corporate functions</h3>\r\n            <ul class=\"cfInf__list\">\r\n              <li class=\"cfInf__li\">\r\n                <span class=\"cfInf__dot\"></span>\r\n                <span>Fragmented HR, Finance, IT, and Risk teams operating in silos with limited collaboration.</span>\r\n              </li>\r\n              <li class=\"cfInf__li\">\r\n                <span class=\"cfInf__dot\"></span>\r\n                <span>Reactive compliance and weak governance across core corporate functions.</span>\r\n              </li>\r\n            </ul>\r\n          </article>\r\n\r\n          <article class=\"cfInf__group\">\r\n            <p class=\"cfInf__groupKicker\">Processes &amp; Cost</p>\r\n            <h3 class=\"cfInf__groupTitle\">Manual, inefficient operations</h3>\r\n            <ul class=\"cfInf__list\">\r\n              <li class=\"cfInf__li\">\r\n                <span class=\"cfInf__dot\"></span>\r\n                <span>Manual workflows, redundant approvals, and low automation maturity across processes.</span>\r\n              </li>\r\n              <li class=\"cfInf__li\">\r\n                <span class=\"cfInf__dot\"></span>\r\n                <span>Inefficient real estate, transportation, and administrative processes driving up overheads.</span>\r\n              </li>\r\n              <li class=\"cfInf__li\">\r\n                <span class=\"cfInf__dot\"></span>\r\n                <span>Outdated systems, poor data integration, and limited AI / analytics adoption.</span>\r\n              </li>\r\n            </ul>\r\n          </article>\r\n\r\n          <article class=\"cfInf__group\">\r\n            <p class=\"cfInf__groupKicker\">People &amp; Performance</p>\r\n            <h3 class=\"cfInf__groupTitle\">Limited visibility and talent risk</h3>\r\n            <ul class=\"cfInf__list\">\r\n              <li class=\"cfInf__li\">\r\n                <span class=\"cfInf__dot\"></span>\r\n                <span>Limited visibility into workforce performance, productivity, and key cost drivers.</span>\r\n              </li>\r\n              <li class=\"cfInf__li\">\r\n                <span class=\"cfInf__dot\"></span>\r\n                <span>High attrition, skill gaps, and misaligned talent strategies across support functions.</span>\r\n              </li>\r\n            </ul>\r\n          </article>\r\n        </div>\r\n\r\n        <!-- SPINE -->\r\n        <div class=\"cfInf__spine\" aria-hidden=\"true\">\r\n          <div class=\"cfInf__spineLine\"></div>\r\n          <div class=\"cfInf__spineLabel cfInf__spineLabel--top\">From fragmented functions</div>\r\n          <div class=\"cfInf__spineNode\">⇄</div>\r\n          <div class=\"cfInf__spineLabel cfInf__spineLabel--bottom\">To an integrated corporate backbone</div>\r\n        </div>\r\n\r\n        <!-- RIGHT: What we enable -->\r\n        <div class=\"cfInf__col cfInf__col--right\">\r\n          <div class=\"cfInf__colHead\">\r\n            <p class=\"cfInf__colTitle\">What we enable</p>\r\n            <p class=\"cfInf__colNote\">Corporate function transformation outcomes</p>\r\n          </div>\r\n\r\n          <article class=\"cfInf__group\">\r\n            <p class=\"cfInf__groupKicker\">Cost &amp; Efficiency</p>\r\n            <h3 class=\"cfInf__groupTitle\">Smarter, leaner corporate operations</h3>\r\n            <ul class=\"cfInf__list\">\r\n              <li class=\"cfInf__li\">\r\n                <span class=\"cfInf__dot\"></span>\r\n                <span><b>15–30% reduction in DFC and overhead costs</b> through automation, shared services, and Lean optimisation.</span>\r\n              </li>\r\n              <li class=\"cfInf__li\">\r\n                <span class=\"cfInf__dot\"></span>\r\n                <span>Real estate and facility cost savings of <b>$15–20M</b> enabled by smart tools and footprint optimisation.</span>\r\n              </li>\r\n            </ul>\r\n          </article>\r\n\r\n          <article class=\"cfInf__group\">\r\n            <p class=\"cfInf__groupKicker\">Governance &amp; Compliance</p>\r\n            <h3 class=\"cfInf__groupTitle\">Unified, transparent governance model</h3>\r\n            <ul class=\"cfInf__list\">\r\n              <li class=\"cfInf__li\">\r\n                <span class=\"cfInf__dot\"></span>\r\n                <span>Unified corporate governance model integrating all enterprise functions with clear charters and decision rights.</span>\r\n              </li>\r\n              <li class=\"cfInf__li\">\r\n                <span class=\"cfInf__dot\"></span>\r\n                <span>Enhanced decision-making and transparency with AI-enabled dashboards and analytics.</span>\r\n              </li>\r\n              <li class=\"cfInf__li\">\r\n                <span class=\"cfInf__dot\"></span>\r\n                <span>Improved compliance maturity aligned with ISO, ESG, and DPDP frameworks.</span>\r\n              </li>\r\n            </ul>\r\n          </article>\r\n\r\n          <article class=\"cfInf__group\">\r\n            <p class=\"cfInf__groupKicker\">People &amp; Future Readiness</p>\r\n            <h3 class=\"cfInf__groupTitle\">Stronger talent and future-ready backbone</h3>\r\n            <ul class=\"cfInf__list\">\r\n              <li class=\"cfInf__li\">\r\n                <span class=\"cfInf__dot\"></span>\r\n                <span>Strengthened talent retention and productivity via predictive HR models and skills insights.</span>\r\n              </li>\r\n              <li class=\"cfInf__li\">\r\n                <span class=\"cfInf__dot\"></span>\r\n                <span>Created a data-driven, future-ready corporate backbone for scale, agility, and enterprise-wide impact.</span>\r\n              </li>\r\n            </ul>\r\n          </article>\r\n        </div>\r\n      </div>\r\n\r\n      <div class=\"cfInf__impact\">\r\n        <div class=\"cfInf__impactRow\">\r\n          <p class=\"cfInf__impactTitle\">Typical impact unlocked</p>\r\n          <div class=\"cfInf__chips\" aria-label=\"Typical corporate function transformation impacts\">\r\n            <span class=\"cfInf__chip\"><i></i>15–30% DFC &amp; overhead cost reduction</span>\r\n            <span class=\"cfInf__chip\"><i></i>AI-enabled transparency &amp; decision support</span>\r\n            <span class=\"cfInf__chip\"><i></i>Higher compliance maturity (ISO &amp; DPDP)</span>\r\n            <span class=\"cfInf__chip\"><i></i>Future-ready corporate backbone</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- ===================== CASE STUDIES – CORPORATE FUNCTION TRANSFORMATION ===================== -->\r\n<style>\r\n  :root{\r\n    /* use same max as Process Advisory spine for visual alignment */\r\n    --pa-max:1320px;\r\n    --pa-text:#020C4F;\r\n    --pa-muted:rgba(2,12,79,0.78);\r\n    --pa-accent:#5040a0;\r\n    --pa-border:rgba(7,15,40,0.06);\r\n    --pa-shadow:0 18px 40px rgba(15,23,42,0.08);\r\n    --pa-radius:20px;\r\n  }\r\n\r\n  .pa-casestudies{\r\n    font-family:Poppins,system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\r\n    background:#f7f8fc;\r\n    padding:70px 20px 90px;\r\n  }\r\n  .pa-cs__wrap{\r\n    max-width:var(--pa-max);\r\n    margin:0 auto;\r\n  }\r\n\r\n  .pa-cs__head{\r\n    display:flex;\r\n    justify-content:space-between;\r\n    align-items:flex-end;\r\n    gap:24px;\r\n    margin-bottom:28px;\r\n  }\r\n  .pa-cs__eyebrow{\r\n    font-size:13px;\r\n    font-weight:600;\r\n    letter-spacing:.14em;\r\n    text-transform:uppercase;\r\n    color:rgba(2,12,79,0.68);\r\n    margin-bottom:8px;\r\n  }\r\n  .pa-cs__title{\r\n    font-size:30px;\r\n    line-height:1.25;\r\n    margin:0;\r\n    color:var(--pa-text);\r\n    font-weight:700;\r\n  }\r\n  .pa-cs__subtitle{\r\n    margin-top:10px;\r\n    max-width:640px;\r\n    font-size:14px;\r\n    line-height:1.7;\r\n    color:var(--pa-muted);\r\n  }\r\n\r\n  .pa-cs__grid{\r\n    display:grid;\r\n    grid-template-columns:repeat(4,minmax(0,1fr));\r\n    gap:20px;\r\n  }\r\n\r\n  .pa-cs__item{\r\n    text-decoration:none;\r\n    color:inherit;\r\n  }\r\n\r\n  .pa-cs__card{\r\n    height:100%;                      /* equal card height */\r\n    border-radius:var(--pa-radius);\r\n    background:#ffffff;\r\n    border:1px solid var(--pa-border);\r\n    box-shadow:var(--pa-shadow);\r\n    padding:16px 16px 18px;\r\n    display:flex;\r\n    flex-direction:column;\r\n    position:relative;\r\n    overflow:hidden;\r\n    transition:transform .2s ease, box-shadow .2s ease, border-color .2s ease, background .2s ease;\r\n  }\r\n\r\n  .pa-cs__card::before{\r\n    content:\"\";\r\n    position:absolute;\r\n    inset:0;\r\n    background:linear-gradient(135deg,rgba(80,64,160,0.06),rgba(31,156,228,0.04));\r\n    opacity:0;\r\n    transition:opacity .2s ease;\r\n    pointer-events:none;\r\n  }\r\n\r\n  .pa-cs__meta-pill{\r\n    position:relative;\r\n    display:inline-flex;\r\n    align-items:center;\r\n    gap:6px;\r\n    padding:5px 10px;\r\n    border-radius:999px;\r\n    background:rgba(80,64,160,0.05);\r\n    color:rgba(2,12,79,0.74);\r\n    font-size:11px;\r\n    font-weight:500;\r\n    margin-bottom:10px;\r\n  }\r\n  .pa-cs__meta-dot{\r\n    width:7px;\r\n    height:7px;\r\n    border-radius:999px;\r\n    background:var(--pa-accent);\r\n  }\r\n\r\n  .pa-cs__title-small{\r\n    position:relative;\r\n    font-size:14px;\r\n    line-height:1.5;\r\n    font-weight:600;\r\n    color:var(--pa-text);\r\n    margin:0 0 8px;\r\n  }\r\n  .pa-cs__body{\r\n    position:relative;\r\n    font-size:12.6px;\r\n    line-height:1.6;\r\n    color:var(--pa-muted);\r\n    margin:0;\r\n    flex:1 1 auto;                    /* makes impact line sit at bottom, equal height */\r\n  }\r\n\r\n  .pa-cs__impact{\r\n    position:relative;\r\n    margin-top:10px;\r\n    font-size:11.5px;\r\n    font-weight:500;\r\n    color:var(--pa-accent);\r\n    display:flex;\r\n    align-items:center;\r\n    gap:6px;\r\n  }\r\n  .pa-cs__impact-dot{\r\n    width:6px;\r\n    height:6px;\r\n    border-radius:999px;\r\n    background:var(--pa-accent);\r\n  }\r\n\r\n  /* hover */\r\n  .pa-cs__card:hover{\r\n    transform:translateY(-4px);\r\n    box-shadow:0 22px 40px rgba(15,23,42,0.16);\r\n    border-color:rgba(80,64,160,0.3);\r\n    background:rgba(255,255,255,0.98);\r\n  }\r\n  .pa-cs__card:hover::before{\r\n    opacity:1;\r\n  }\r\n\r\n  /* responsive */\r\n  @media (max-width:1200px){\r\n    .pa-cs__grid{\r\n      grid-template-columns:repeat(3,minmax(0,1fr));\r\n    }\r\n  }\r\n  @media (max-width:900px){\r\n    .pa-cs__grid{\r\n      grid-template-columns:repeat(2,minmax(0,1fr));\r\n    }\r\n  }\r\n  @media (max-width:640px){\r\n    .pa-casestudies{\r\n      padding:50px 16px 70px;\r\n    }\r\n    .pa-cs__head{\r\n      flex-direction:column;\r\n      align-items:flex-start;\r\n      gap:12px;\r\n    }\r\n    .pa-cs__title{\r\n      font-size:26px;\r\n    }\r\n    .pa-cs__grid{\r\n      grid-template-columns:1fr;\r\n      gap:16px;\r\n    }\r\n    .pa-cs__card{\r\n      padding:14px 14px 16px;\r\n    }\r\n  }\r\n</style>\r\n\r\n<section class=\"pa-casestudies\" id=\"corporate-function-casestudies\">\r\n  <div class=\"pa-cs__wrap\">\r\n\r\n    <!-- Header -->\r\n    <div class=\"pa-cs__head\">\r\n      <div>\r\n        <div class=\"pa-cs__eyebrow\">Corporate Function Transformation</div>\r\n        <h2 class=\"pa-cs__title\">Representative Corporate Function Engagements</h2>\r\n        <p class=\"pa-cs__subtitle\">\r\n          Selected programs where we have transformed HR, Finance, Risk, Facilities, and IT\r\n          into a unified, data-driven corporate backbone.\r\n        </p>\r\n      </div>\r\n    </div>\r\n\r\n    <!-- 4 × 2 Grid -->\r\n    <div class=\"pa-cs__grid\">\r\n\r\n      <!-- 1 -->\r\n      <a class=\"pa-cs__item\" href=\"https://mediumpurple-ant-531485.hostingersite.com/contact-us/\">\r\n        <div class=\"pa-cs__card\">\r\n          <div class=\"pa-cs__meta-pill\">\r\n            <span class=\"pa-cs__meta-dot\"></span>\r\n            Large Diversified Enterprise · HR\r\n          </div>\r\n          <h3 class=\"pa-cs__title-small\">\r\n            HR function shared services &amp; talent-at-risk model\r\n          </h3>\r\n          <p class=\"pa-cs__body\">\r\n            Established an outsourced shared services model, AI / ML-based “Save Talent at Risk”\r\n            profiling, and Development Councils, with a refreshed EVP aligned to culture.\r\n          </p>\r\n          <div class=\"pa-cs__impact\">\r\n            <span class=\"pa-cs__impact-dot\"></span>\r\n            35% reduction in HR operating costs · Higher engagement and retention\r\n          </div>\r\n        </div>\r\n      </a>\r\n\r\n      <!-- 2 -->\r\n      <a class=\"pa-cs__item\" href=\"https://mediumpurple-ant-531485.hostingersite.com/contact-us/\">\r\n        <div class=\"pa-cs__card\">\r\n          <div class=\"pa-cs__meta-pill\">\r\n            <span class=\"pa-cs__meta-dot\"></span>\r\n            Large GCC · Facilities &amp; Real Estate\r\n          </div>\r\n          <h3 class=\"pa-cs__title-small\">\r\n            Data-driven facilities and real estate optimisation\r\n          </h3>\r\n          <p class=\"pa-cs__body\">\r\n            Optimised transportation and real estate through AI-enabled routing, seat utilisation\r\n            dashboards, and an intelligent “Book My Seat” platform.\r\n          </p>\r\n          <div class=\"pa-cs__impact\">\r\n            <span class=\"pa-cs__impact-dot\"></span>\r\n            $5M annual transport savings · $20M real estate optimisation over 3 years\r\n          </div>\r\n        </div>\r\n      </a>\r\n\r\n      <!-- 3 -->\r\n      <a class=\"pa-cs__item\" href=\"https://mediumpurple-ant-531485.hostingersite.com/contact-us/\">\r\n        <div class=\"pa-cs__card\">\r\n          <div class=\"pa-cs__meta-pill\">\r\n            <span class=\"pa-cs__meta-dot\"></span>\r\n            Large Captive Shared Services · Finance\r\n          </div>\r\n          <h3 class=\"pa-cs__title-small\">\r\n            End-to-end invoicing workflow transformation\r\n          </h3>\r\n          <p class=\"pa-cs__body\">\r\n            Conducted a lean diagnostic of invoicing, redesigned workflows and templates,\r\n            and eliminated redundant handoffs through automation and governance.\r\n          </p>\r\n          <div class=\"pa-cs__impact\">\r\n            <span class=\"pa-cs__impact-dot\"></span>\r\n            MI closure cut from WD+22 to WD+10 · Invoicing issues &lt;1% from 25%\r\n          </div>\r\n        </div>\r\n      </a>\r\n\r\n      <!-- 4 -->\r\n      <a class=\"pa-cs__item\" href=\"https://mediumpurple-ant-531485.hostingersite.com/contact-us/\">\r\n        <div class=\"pa-cs__card\">\r\n          <div class=\"pa-cs__meta-pill\">\r\n            <span class=\"pa-cs__meta-dot\"></span>\r\n            BFSI Leader · Risk &amp; Compliance\r\n          </div>\r\n          <h3 class=\"pa-cs__title-small\">\r\n            GRC digitisation aligned with ISO &amp; DPDP\r\n          </h3>\r\n          <p class=\"pa-cs__body\">\r\n            Transformed the enterprise GRC framework with real-time risk dashboards, automated\r\n            issue tracking, and AI-enabled risk scoring and compliance alerts.\r\n          </p>\r\n          <div class=\"pa-cs__impact\">\r\n            <span class=\"pa-cs__impact-dot\"></span>\r\n            50% faster audit preparation · Proactive, data-driven risk culture\r\n          </div>\r\n        </div>\r\n      </a>\r\n\r\n      <!-- 5 -->\r\n      <a class=\"pa-cs__item\" href=\"https://mediumpurple-ant-531485.hostingersite.com/contact-us/\">\r\n        <div class=\"pa-cs__card\">\r\n          <div class=\"pa-cs__meta-pill\">\r\n            <span class=\"pa-cs__meta-dot\"></span>\r\n            Global GCC · IT Resilience &amp; BCP\r\n          </div>\r\n          <h3 class=\"pa-cs__title-small\">\r\n            Integrated IT resilience &amp; business continuity framework\r\n          </h3>\r\n          <p class=\"pa-cs__body\">\r\n            Built an integrated IT and BCP framework with automated backups, DR readiness checks,\r\n            and multi-zone failover architecture across regions.\r\n          </p>\r\n          <div class=\"pa-cs__impact\">\r\n            <span class=\"pa-cs__impact-dot\"></span>\r\n            60% improvement in recovery time · Zero critical service disruptions\r\n          </div>\r\n        </div>\r\n      </a>\r\n\r\n      <!-- 6 -->\r\n      <a class=\"pa-cs__item\" href=\"https://mediumpurple-ant-531485.hostingersite.com/contact-us/\">\r\n        <div class=\"pa-cs__card\">\r\n          <div class=\"pa-cs__meta-pill\">\r\n            <span class=\"pa-cs__meta-dot\"></span>\r\n            Global Organisation · Facilities &amp; Admin\r\n          </div>\r\n          <h3 class=\"pa-cs__title-small\">\r\n            Facilities &amp; administration optimisation program\r\n          </h3>\r\n          <p class=\"pa-cs__body\">\r\n            Deployed a digital command centre, standardised vendor governance, and introduced\r\n            real-time energy tracking and predictive maintenance.\r\n          </p>\r\n          <div class=\"pa-cs__impact\">\r\n            <span class=\"pa-cs__impact-dot\"></span>\r\n            20% reduction in operating costs · Stronger sustainability metrics\r\n          </div>\r\n        </div>\r\n      </a>\r\n\r\n      <!-- 7 -->\r\n      <a class=\"pa-cs__item\" href=\"https://mediumpurple-ant-531485.hostingersite.com/contact-us/\">\r\n        <div class=\"pa-cs__card\">\r\n          <div class=\"pa-cs__meta-pill\">\r\n            <span class=\"pa-cs__meta-dot\"></span>\r\n            Financial Services Enterprise · HR\r\n          </div>\r\n          <h3 class=\"pa-cs__title-small\">\r\n            HR capability &amp; culture transformation roadmap\r\n          </h3>\r\n          <p class=\"pa-cs__body\">\r\n            Designed a multi-year HR transformation covering leadership, performance, and capability\r\n            building, with behavioural models and data-driven learning journeys.\r\n          </p>\r\n          <div class=\"pa-cs__impact\">\r\n            <span class=\"pa-cs__impact-dot\"></span>\r\n            Higher engagement scores · Stronger readiness for digital transformation\r\n          </div>\r\n        </div>\r\n      </a>\r\n\r\n      <!-- 8 -->\r\n      <a class=\"pa-cs__item\" href=\"https://mediumpurple-ant-531485.hostingersite.com/contact-us/\">\r\n        <div class=\"pa-cs__card\">\r\n          <div class=\"pa-cs__meta-pill\">\r\n            <span class=\"pa-cs__meta-dot\"></span>\r\n            PE-backed Group · Corporate Functions\r\n          </div>\r\n          <h3 class=\"pa-cs__title-small\">\r\n            Integrated corporate function synergy program\r\n          </h3>\r\n          <p class=\"pa-cs__body\">\r\n            Integrated HR, Finance, and Risk under a unified governance structure with shared services,\r\n            KPI alignment, and digital dashboards for a PE-backed manufacturer.\r\n          </p>\r\n          <div class=\"pa-cs__impact\">\r\n            <span class=\"pa-cs__impact-dot\"></span>\r\n            $5M annual efficiency savings · Accelerated IPO readiness\r\n          </div>\r\n        </div>\r\n      </a>\r\n\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- ===================== CORPORATE FUNCTION – HOW WE BUILD THE BACKBONE (IMAGE + ICON LAYOUT) ===================== -->\r\n<style>\r\n  .pa-hwdt{\r\n    font-family:Poppins,system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\r\n    padding:100px 20px;\r\n    background:#ffffff;\r\n  }\r\n  .pa-hwdt-wrap{\r\n    max-width:1320px; /* aligned to corporate function spine */\r\n    margin:0 auto;\r\n  }\r\n\r\n  /* header */\r\n  .pa-hwdt-head{\r\n    text-align:center;\r\n    max-width:900px;\r\n    margin:0 auto 60px;\r\n  }\r\n  .pa-hwdt-eyebrow{\r\n    font-size:13px;\r\n    font-weight:600;\r\n    letter-spacing:.14em;\r\n    text-transform:uppercase;\r\n    color:rgba(2,12,79,.6);\r\n    margin-bottom:12px;\r\n  }\r\n  .pa-hwdt-title{\r\n    font-size:36px;\r\n    line-height:1.2;\r\n    color:#020C4F;\r\n    font-weight:700;\r\n    margin:0 0 16px;\r\n  }\r\n  .pa-hwdt-sub{\r\n    font-size:18px;\r\n    line-height:1.7;\r\n    color:rgba(2,12,79,.85);\r\n  }\r\n\r\n  /* layout */\r\n  .pa-hwdt-grid{\r\n    display:grid;\r\n    grid-template-columns:1fr 1fr;\r\n    gap:70px;\r\n    align-items:stretch;\r\n  }\r\n\r\n  /* image */\r\n  .pa-hwdt-image{\r\n    height:100%;\r\n  }\r\n  .pa-hwdt-image img{\r\n    width:100%;\r\n    height:100%;\r\n    min-height:520px;\r\n    object-fit:cover;\r\n    border-radius:18px;\r\n    display:block;\r\n  }\r\n\r\n  /* list */\r\n  .pa-hwdt-list{\r\n    display:flex;\r\n    flex-direction:column;\r\n    justify-content:center;\r\n    gap:26px;\r\n  }\r\n  .pa-hwdt-item{\r\n    display:grid;\r\n    grid-template-columns:42px 1fr;\r\n    gap:18px;\r\n    align-items:flex-start;\r\n  }\r\n\r\n  .pa-hwdt-icon{\r\n    width:36px;\r\n    height:36px;\r\n    border-radius:10px;\r\n    background:rgba(80,64,160,.08);\r\n    display:flex;\r\n    align-items:center;\r\n    justify-content:center;\r\n    flex-shrink:0;\r\n  }\r\n  .pa-hwdt-icon svg{\r\n    width:18px;\r\n    height:18px;\r\n    stroke:rgba(80,64,160,.9);\r\n  }\r\n\r\n  .pa-hwdt-item h3{\r\n    font-size:17px;\r\n    margin:0 0 6px;\r\n    color:#020C4F;\r\n    font-weight:600;\r\n  }\r\n  .pa-hwdt-item p{\r\n    font-size:14px;\r\n    line-height:1.7;\r\n    margin:0;\r\n    color:rgba(2,12,79,.78);\r\n  }\r\n\r\n  /* responsive */\r\n  @media (max-width:900px){\r\n    .pa-hwdt-grid{\r\n      grid-template-columns:1fr;\r\n      gap:50px;\r\n    }\r\n    .pa-hwdt-image img{\r\n      min-height:360px;\r\n    }\r\n    .pa-hwdt-title{\r\n      font-size:30px;\r\n    }\r\n    .pa-hwdt-sub{\r\n      font-size:16px;\r\n    }\r\n  }\r\n</style>\r\n\r\n<section class=\"pa-hwdt\" id=\"corporate-function-how-we-work\">\r\n  <div class=\"pa-hwdt-wrap\">\r\n\r\n    <!-- Header -->\r\n    <div class=\"pa-hwdt-head\">\r\n      <div class=\"pa-hwdt-eyebrow\">Corporate Function</div>\r\n      <h2 class=\"pa-hwdt-title\">How We Build an Integrated Corporate Backbone</h2>\r\n      <p class=\"pa-hwdt-sub\">\r\n        <strong>Corporate Function Transformation is not a cost-cutting exercise.</strong><br/>\r\n        It is the redesign of HR, Finance, IT, Risk, and other functions into a single, data-driven\r\n        backbone that underpins growth, control, and enterprise agility.\r\n      </p>\r\n    </div>\r\n\r\n    <!-- Content -->\r\n    <div class=\"pa-hwdt-grid\">\r\n\r\n      <!-- Image -->\r\n      <div class=\"pa-hwdt-image\">\r\n        <img\r\n          src=\"https://images.pexels.com/photos/1181406/pexels-photo-1181406.jpeg\"\r\n          alt=\"Leadership team reviewing integrated corporate function operating model\"\r\n          loading=\"lazy\"\r\n        />\r\n      </div>\r\n\r\n      <!-- Pillars -->\r\n      <div class=\"pa-hwdt-list\">\r\n\r\n        <div class=\"pa-hwdt-item\">\r\n          <div class=\"pa-hwdt-icon\">\r\n            <!-- operating model / org map icon -->\r\n            <svg fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\">\r\n              <rect x=\"3\" y=\"3\" width=\"7\" height=\"7\" rx=\"2\"/>\r\n              <rect x=\"14\" y=\"3\" width=\"7\" height=\"7\" rx=\"2\"/>\r\n              <rect x=\"3\" y=\"14\" width=\"7\" height=\"7\" rx=\"2\"/>\r\n              <path d=\"M10 6.5h4M6.5 10v4M17.5 10v4M10 17.5h4\"/>\r\n            </svg>\r\n          </div>\r\n          <div>\r\n            <h3>Design an integrated operating model</h3>\r\n            <p>\r\n              We connect HR, Finance, IT, Risk, Facilities, and other functions into a single,\r\n              coordinated corporate backbone with clear mandates and interfaces.\r\n            </p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"pa-hwdt-item\">\r\n          <div class=\"pa-hwdt-icon\">\r\n            <!-- shared services / hubs icon -->\r\n            <svg fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\">\r\n              <circle cx=\"12\" cy=\"12\" r=\"3\"/>\r\n              <path d=\"M12 5V3M19 12h2M12 21v-2M3 12h2M6 6l1.5 1.5M18 6l-1.5 1.5M18 18l-1.5-1.5M6 18l1.5-1.5\"/>\r\n            </svg>\r\n          </div>\r\n          <div>\r\n            <h3>Create shared services and centres of excellence</h3>\r\n            <p>\r\n              We consolidate transactional work into shared services and build COEs for talent,\r\n              analytics, and risk so that expertise is deep and scalable.\r\n            </p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"pa-hwdt-item\">\r\n          <div class=\"pa-hwdt-icon\">\r\n            <!-- automation / workflow icon -->\r\n            <svg fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\">\r\n              <rect x=\"3\" y=\"4\" width=\"7\" height=\"6\" rx=\"1.5\"/>\r\n              <rect x=\"14\" y=\"14\" width=\"7\" height=\"6\" rx=\"1.5\"/>\r\n              <path d=\"M10 7h4a3 3 0 0 1 3 3v1M7 10v4a3 3 0 0 0 3 3h4\"/>\r\n            </svg>\r\n          </div>\r\n          <div>\r\n            <h3>Digitise workflows and embed automation</h3>\r\n            <p>\r\n              We simplify policies, digitise approvals, and integrate core systems so that\r\n              employees and partners experience faster, seamless corporate services.\r\n            </p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"pa-hwdt-item\">\r\n          <div class=\"pa-hwdt-icon\">\r\n            <!-- governance / shield icon -->\r\n            <svg fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\">\r\n              <path d=\"M12 3 5 6v5c0 4.28 2.8 8.11 7 9 4.2-.89 7-4.72 7-9V6l-7-3z\"/>\r\n              <path d=\"M9.5 12.5 11 14l3.5-3.5\"/>\r\n            </svg>\r\n          </div>\r\n          <div>\r\n            <h3>Strengthen governance, risk, and compliance</h3>\r\n            <p>\r\n              We clarify decision rights, control points, and risk ownership, supported by\r\n              dashboards that give leadership real-time visibility across functions.\r\n            </p>\r\n          </div>\r\n        </div>\r\n\r\n        <div class=\"pa-hwdt-item\">\r\n          <div class=\"pa-hwdt-icon\">\r\n            <!-- people / capability icon -->\r\n            <svg fill=\"none\" viewBox=\"0 0 24 24\" stroke-width=\"2\">\r\n              <circle cx=\"8\" cy=\"8\" r=\"3\"/>\r\n              <circle cx=\"17\" cy=\"8\" r=\"3\"/>\r\n              <path d=\"M3 20v-1a4 4 0 0 1 4-4h2\"/>\r\n              <path d=\"M15 15h2a4 4 0 0 1 4 4v1\"/>\r\n              <path d=\"M11 20h4.5M13 17v5\"/>\r\n            </svg>\r\n          </div>\r\n          <div>\r\n            <h3>Build leadership, capability, and change muscle</h3>\r\n            <p>\r\n              We help corporate function leaders reframe their role, build new skills,\r\n              and establish routines that sustain discipline and continuous improvement.\r\n            </p>\r\n          </div>\r\n        </div>\r\n\r\n      </div>\r\n    </div>\r\n  </div>\r\n</section>\r\n\r\n<!-- ===================== CORPORATE FUNCTION – WHERE LEADERS CALL US IN (CTA SECTION) ===================== -->\r\n<style>\r\n  :root{\r\n    --cta-bg-1:#f5f3ff;\r\n    --cta-bg-2:#eaf4ff;\r\n    --cta-text:#020C4F;\r\n    --cta-accent:#5040a0;\r\n    --cta-border:rgba(2,12,79,.12);\r\n  }\r\n\r\n  .wlcta{\r\n    font-family:Poppins,system-ui,-apple-system,Segoe UI,Roboto,Arial,sans-serif;\r\n    background:radial-gradient(circle at top left,var(--cta-bg-1),var(--cta-bg-2));\r\n    padding:90px 20px;\r\n  }\r\n  .wlcta-wrap{\r\n    max-width:1320px; /* aligned with Corporate Function layout */\r\n    margin:0 auto;\r\n    text-align:center;\r\n  }\r\n\r\n  .wlcta-eyebrow{\r\n    font-size:13px;\r\n    font-weight:600;\r\n    letter-spacing:.14em;\r\n    text-transform:uppercase;\r\n    color:rgba(2,12,79,.6);\r\n    margin-bottom:12px;\r\n  }\r\n  .wlcta-title{\r\n    font-size:34px;\r\n    line-height:1.25;\r\n    color:var(--cta-text);\r\n    font-weight:700;\r\n    margin:0 0 18px;\r\n  }\r\n  .wlcta-intro{\r\n    max-width:780px;\r\n    margin:0 auto 46px;\r\n    font-size:17px;\r\n    line-height:1.7;\r\n    color:rgba(2,12,79,.82);\r\n  }\r\n\r\n  /* triggers */\r\n  .wlcta-grid{\r\n    display:grid;\r\n    grid-template-columns:repeat(3,minmax(0,1fr));\r\n    gap:26px;\r\n    margin-bottom:52px;\r\n  }\r\n  .wlcta-item{\r\n    padding:22px 22px 24px;\r\n    border:1px solid var(--cta-border);\r\n    border-radius:18px;\r\n    background:rgba(255,255,255,.75);\r\n    backdrop-filter:blur(8px);\r\n    text-align:left;\r\n  }\r\n  .wlcta-item h3{\r\n    font-size:16px;\r\n    margin:0 0 8px;\r\n    color:var(--cta-text);\r\n    font-weight:600;\r\n  }\r\n  .wlcta-item p{\r\n    font-size:14px;\r\n    line-height:1.65;\r\n    margin:0;\r\n    color:rgba(2,12,79,.78);\r\n  }\r\n\r\n  /* CTA */\r\n  .wlcta-action{\r\n    display:flex;\r\n    justify-content:center;\r\n  }\r\n  .wlcta-btn{\r\n    display:inline-flex;\r\n    align-items:center;\r\n    gap:10px;\r\n    padding:14px 28px;\r\n    border-radius:999px;\r\n    background:var(--cta-accent);\r\n    color:#fff;\r\n    font-size:14px;\r\n    font-weight:500;\r\n    text-decoration:none;\r\n    box-shadow:0 18px 36px rgba(80,64,160,.35);\r\n    transition:transform .18s ease, box-shadow .18s ease;\r\n  }\r\n  .wlcta-btn span{\r\n    display:inline-flex;\r\n    width:20px;\r\n    height:20px;\r\n    border-radius:999px;\r\n    background:rgba(255,255,255,.18);\r\n    justify-content:center;\r\n    align-items:center;\r\n    font-size:14px;\r\n  }\r\n  .wlcta-btn:hover{\r\n    transform:translateY(-2px);\r\n    box-shadow:0 26px 48px rgba(80,64,160,.45);\r\n  }\r\n\r\n  @media (max-width:1024px){\r\n    .wlcta-grid{\r\n      grid-template-columns:repeat(2,minmax(0,1fr));\r\n    }\r\n  }\r\n  @media (max-width:640px){\r\n    .wlcta{\r\n      padding:70px 16px;\r\n    }\r\n    .wlcta-title{\r\n      font-size:28px;\r\n    }\r\n    .wlcta-grid{\r\n      grid-template-columns:1fr;\r\n      gap:18px;\r\n    }\r\n  }\r\n</style>\r\n\r\n<section class=\"wlcta\" id=\"corporate-function-triggers\">\r\n  <div class=\"wlcta-wrap\">\r\n\r\n    <div class=\"wlcta-eyebrow\">Corporate Function Triggers</div>\r\n    <h2 class=\"wlcta-title\">Where Leaders Typically Call Us In</h2>\r\n    <p class=\"wlcta-intro\">\r\n      Leaders rarely call us just to “optimise HR or Finance”.\r\n      They call when corporate functions are fragmented, cost-heavy, or slowing the business —\r\n      and an integrated, data-driven backbone becomes essential.\r\n    </p>\r\n\r\n    <div class=\"wlcta-grid\">\r\n\r\n      <div class=\"wlcta-item\">\r\n        <h3>Support costs rising faster than growth</h3>\r\n        <p>\r\n          DFC and overheads are expanding year-on-year, but productivity, service quality,\r\n          and business enablement are not improving at the same pace.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"wlcta-item\">\r\n        <h3>Fragmented, overlapping corporate functions</h3>\r\n        <p>\r\n          Multiple HR, Finance, IT, and Risk teams operate in silos, with duplicated work,\r\n          unclear mandates, and no single view of enterprise productivity.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"wlcta-item\">\r\n        <h3>Decisions and approvals are too slow</h3>\r\n        <p>\r\n          Critical decisions are stuck in manual approvals, email loops, and unclear decision rights,\r\n          impacting speed to market and internal experience.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"wlcta-item\">\r\n        <h3>Audit, risk & compliance issues keep repeating</h3>\r\n        <p>\r\n          Findings are addressed locally, but root causes sit across functions, systems,\r\n          and processes — so the same issues resurface year after year.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"wlcta-item\">\r\n        <h3>Digital investments not showing visible impact</h3>\r\n        <p>\r\n          ERPs, HCMs, CRMs, or GRC tools have been deployed, yet manual workarounds,\r\n          spreadsheets, and shadow processes continue to dominate.\r\n        </p>\r\n      </div>\r\n\r\n      <div class=\"wlcta-item\">\r\n        <h3>No single view of corporate function performance</h3>\r\n        <p>\r\n          Leaders see multiple reports from different functions, but lack a simple,\r\n          governed view of cost, service levels, and value delivered by the backbone.\r\n        </p>\r\n      </div>\r\n\r\n    </div>\r\n\r\n    <div class=\"wlcta-action\">\r\n      <a class=\"wlcta-btn\"\r\n         href=\"https://mediumpurple-ant-531485.hostingersite.com/contact-us/\">\r\n        Discuss your corporate function priorities\r\n        <span>→</span>\r\n      </a>\r\n    </div>\r\n\r\n  </div>\r\n</section>";
